"""Legacy sensor reading processor — DO NOT EDIT THIS FILE.

This is the STARTING CODE the coder receives. It is intentionally messy.
The coder writes the refactored version as `legacy_processor.py`.
"""


def process_readings(d, t=100.0):
    # d is list of readings, t is alert threshold
    ok = 0
    bad = 0
    byu = {}
    alerts = []
    for r in d:
        # extract fields
        sid = r.get("sensor_id", "unknown")
        v = r.get("value")
        u = r.get("unit", "raw")
        # skip invalid
        if v is None:
            bad += 1
            continue
        if v < 0:
            bad += 1
            continue
        if u not in ["C", "F", "Pa", "V", "A", "rpm", "pct"]:
            bad += 1
            continue
        # valid
        ok += 1
        # by-unit aggregation
        if u not in byu:
            byu[u] = {"vals": []}
        byu[u]["vals"].append(v)
        # alert check
        if v > t:
            alerts.append({"sensor_id": sid, "value": v, "threshold": t})
    # summarize
    byu2 = {}
    for u in byu:
        lst = byu[u]["vals"]
        byu2[u] = {}
        byu2[u]["count"] = len(lst)
        byu2[u]["avg"] = sum(lst) / len(lst) if lst else 0
        byu2[u]["max"] = max(lst) if lst else 0
        byu2[u]["min"] = min(lst) if lst else 0
    # return result
    return {
        "total_readings": len(d),
        "valid_readings": ok,
        "invalid_readings": bad,
        "by_unit": byu2,
        "alerts": alerts,
    }
